def find_words(board, words); trie = {}; words.each do |word|; node = trie; word.each_char do |letter|; node[letter] ||= {}; node = node[letter]; end; node[:word] = word; end; result = []; rows = board.length; columns = board[0].length; visit = lambda do |row, column, parent|; letter = board[row][column]; node = parent[letter]; return unless node; word = node.delete(:word); result << word if word; board[row][column] = "#"; visit.call(row - 1, column, node) if row > 0; visit.call(row + 1, column, node) if row + 1 < rows; visit.call(row, column - 1, node) if column > 0; visit.call(row, column + 1, node) if column + 1 < columns; board[row][column] = letter; parent.delete(letter) if node.empty?; end; rows.times { |row| columns.times { |column| visit.call(row, column, trie) } }; result; end
